// Target Function Signature
int func_add(int a, int b) { return a + b; }

// 1. Typedef for Function Pointer Type (Recommended)
typedef int (*MathOpPtr)(int a, int b);

// 2. Declaration, Assignment, and Typed Invocation
MathOpPtr fp_typed = func_add;
int result_A = fp_typed(2, 3);

// 3. Raw Declaration Syntax (The Hard Way)
int (*fp_raw)(int, int) = &func_add;

// 4. Raw Invocation Styles (Dereference optional)
int result_B = fp_raw(5, 5);
int result_C = (*fp_raw)(10, 1);

// 5. Callback Registration Example
void register_op(MathOpPtr callback)
{
    // Use callback(x, y);
}
